-- Add testTrackingCode to campaigns
ALTER TABLE "campaigns" ADD COLUMN IF NOT EXISTS "testTrackingCode" VARCHAR(16);

-- Backfill existing rows with a unique-enough placeholder derived from the PK.
-- New campaigns get a real 8-char base58 code generated by the app on create.
UPDATE "campaigns"
SET "testTrackingCode" = substring(replace(encode(decode(replace("id"::text, '-', ''), 'hex'), 'base64'), '/', '_') from 1 for 8)
WHERE "testTrackingCode" IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS "campaigns_testTrackingCode_key" ON "campaigns"("testTrackingCode");
